public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length != end.length) {
        return "cannot be travelled";
    }
    int dim = start.length;
    // Quick check if start equals end
    boolean same = true;
    for (int i = 0; i < dim; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p == null || p.length != 2 * dim) {
            continue; // skip invalid path
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < dim; i++) {
            sb.append(p[i]);
            if (i < dim - 1) sb.append(',');
        }
        String a = sb.toString();
        sb.setLength(0);
        for (int i = dim; i < 2 * dim; i++) {
            sb.append(p[i]);
            if (i < 2 * dim - 1) sb.append(',');
        }
        String b = sb.toString();

        adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }

    StringBuilder sbStart = new StringBuilder();
    for (int i = 0; i < dim; i++) {
        sbStart.append(start[i]);
        if (i < dim - 1) sbStart.append(',');
    }
    String startKey = sbStart.toString();

    StringBuilder sbEnd = new StringBuilder();
    for (int i = 0; i < dim; i++) {
        sbEnd.append(end[i]);
        if (i < dim - 1) sbEnd.append(',');
    }
    String endKey = sbEnd.toString();

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = adj.getOrDefault(cur, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

