    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--;
            } else {
                insertions++;
                // balance remains 0
            }
        }
    }
    insertions += balance; // need closing brackets for remaining opens
    return insertions;
}

