}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        for (int j = 0; j < n; j++) {
            memo[i][j] = -1;
        }
    }
    int total = 0;
    for (int i = 0; i < n; i++) {
        total += dfs(1 << i, i, A, memo, fullMask);
    }
    return total;
}

private static int dfs(int mask, int last, int[] A, int[][] memo, int fullMask) {
    if (mask == fullMask) return 1;
    if (memo[mask][last] != -1) return memo[mask][last];
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if ((mask & (1 << i)) == 0) {
            int sum = A[last] + A[i];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                count += dfs(mask | (1 << i), i, A, memo, fullMask);
            }
        }
    }
    memo[mask][last] = count;
    return count;
}

public static int largestRectangleArea(int[] heights) {
