    java.util.Stack<Integer> stack = new java.util.Stack<>();
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int k = 0; k < m + n - 1; k++) {
        if (k % 2 == 0) {
            int i = Math.min(k, m - 1);
            int j = k - i;
            while (i >= 0 && j < n) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(k, n - 1);
            int i = k - j;
            while (j >= 0 && i < m) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no larger permutation exists
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix starting at i+1
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    return Integer.parseInt(new String(digits));
}

public static List<String> centerSymmetricNumbers(int n) {
    return build(n, n);
}

private static List<String> build(int current, int total) {
    if (current == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (current == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }
    List<String> prev = build(current - 2, total);
    List<String> result = new ArrayList<>();
    for (String s : prev) {
        if (current != total) {
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for duplicate points
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Compute twice the area of the triangle (shoelace formula)
    int area2 = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);
    return area2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>();
    if (n <= 0) return res;
    long curr = 1;
    for (int i = 0; i < n; i++) {
        res.add((int) curr);
        if (curr * 10 <= n) {
            curr *= 10;
        } else {
            if (curr % 10 != 9 && curr + 1 <= n) {
                curr++;
            } else {
                while ((curr / 10) % 10 == 9 || curr + 1 > n) {
                    curr /= 10;
                }
                curr++;
            }
        }
    }
    return res;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    int n = s.length();
    while (i < n) {
        if (s.charAt(i) == ' ') {
            result.append(' ');
            i++;
        } else {
            int start = i;
            while (i < n && s.charAt(i) != ' ') {
                i++;
            }
            String word = s.substring(start, i);
            result.append(new StringBuilder(word).reverse());
        }
    }
    return result.toString();
}
